import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function raw_events_table_exists(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM system.tables WHERE database = 'analytics' AND name = 'raw_events'",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count === 1;
  return {
    passed,
    message: passed ? "Raw events table exists." : `Expected 1 table, got ${count}.`,
    details: { count },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function table_has_ttl(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ create_table_query: string }>(
    ctx,
    "SELECT create_table_query FROM system.tables WHERE database = 'analytics' AND name = 'raw_events'",
  );
  const query = rows[0]?.create_table_query ?? "";
  const hasTtl = /TTL\s+event_ts|TTL\s+\w+\s*\+|ttl/i.test(query);
  const has90 = /90|interval\s+90/i.test(query);
  const passed = hasTtl && has90;
  return {
    passed,
    message: passed ? "Table has TTL (90 days)." : "Table missing TTL or wrong interval.",
    details: { hasTtl, has90 },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function table_has_event_ts_column(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ name: string }>(
    ctx,
    "SELECT name FROM system.columns WHERE database = 'analytics' AND table = 'raw_events'",
  );
  const names = rows.map((r) => r.name);
  const hasEventTs = names.includes("event_ts");
  return {
    passed: hasEventTs,
    message: hasEventTs ? "Table has event_ts column." : `Missing event_ts. Got: ${JSON.stringify(names)}.`,
    details: { names },
  };
}

export async function no_hardcoded_connection_strings(): Promise<AssertionResult> {
  return scanWorkspaceForHardcodedConnections();
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { hasReadmeOrDocs, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function connection_env_vars_available(ctx: AssertionContext): Promise<AssertionResult> {
  const hasClickHouse = Boolean(ctx.env("CLICKHOUSE_URL"));
  return {
    passed: hasClickHouse,
    message: hasClickHouse ? "Connection env vars available." : "Missing CLICKHOUSE_URL.",
    details: { hasClickHouse },
